def dispatch(line):
    parts = line.split()
    if not parts:
        return ""
    command, text = parts[0], " ".join(parts[1:])
    actions = {"upper": lambda s: s.upper(), "len": lambda s: str(len(s)), "rev": lambda s: s[::-1]}
    handler = actions.get(command)
    return handler(text) if handler else f"Неизвестная команда: {command}"

